// Extract request payload safely
const body = $json.body || $json;

const senderName = body.senderName || 'Sender';
const senderEmail = body.senderEmail || '';
const recipient = body.recipient || 'recipient@example.com';
const reason = body.reason || 'Follow up';
const attachments = Array.isArray(body.attachments) ? body.attachments : [];
const attachmentSummary = body.attachmentSummary || '';

// Format attached files and Google Drive links for text display
let filesContext = 'No attachments';
if (attachments.length > 0) {
  filesContext = attachments.map((att, index) => {
    if (att.source === 'google_drive') {
      return `• [Google Drive Link] ${att.name || 'Document'}: ${att.url}`;
    }
    const sizeKb = att.size ? `${Math.round(att.size / 1024)} KB` : 'file';
    return `• [Computer Upload] ${att.name || 'Attachment'} (${sizeKb})`;
  }).join('\n');
}

return {
  senderName,
  senderEmail,
  recipient,
  reason,
  attachments,
  filesContext
};

const item = $json;
const attachments = Array.isArray(item.attachments) ? item.attachments : [];

// Extract subject
let subject = item.reason.length > 50 ? item.reason.substring(0, 47) + '...' : item.reason;
if (!subject.toLowerCase().startsWith('regarding') && !subject.toLowerCase().startsWith('update')) {
  subject = `Update: ${subject}`;
}

// Build plain text message
let bodyText = `Hi there,\n\nI hope you are having a productive week.\n\n${item.reason}\n`;
if (attachments.length > 0) {
  bodyText += `\nPlease find the relevant attachment(s) referenced below:\n${item.filesContext}\n`;
}
bodyText += `\nPlease let me know if you have any questions or need further details.\n\nBest regards,\n${item.senderName}\n${item.senderEmail}`;

// Build HTML File Retrieval Container
let fileContainerHtml = '';
if (attachments.length > 0) {
  const fileCards = attachments.map((att, i) => {
    if (att.source === 'google_drive') {
      return `<div style="padding: 10px 14px; background: #ffffff; border: 1px solid #d2e3fc; border-radius: 8px; margin-bottom: 8px;">` +
        `<span style="background: #e8f0fe; color: #1a73e8; font-size: 11px; font-weight: 700; padding: 2px 6px; border-radius: 4px; text-transform: uppercase;">Google Drive</span> ` +
        `<strong>${att.name || 'Document'}</strong><br/>` +
        `<a href="${att.url}" target="_blank" style="display: inline-block; margin-top: 6px; color: #1a73e8; text-decoration: underline; font-size: 13px; font-weight: 600;">Open File in Google Drive &rarr;</a>` +
        `</div>`;
    }
    const sizeKb = att.size ? `${Math.round(att.size / 1024)} KB` : 'file';
    return `<div style="padding: 10px 14px; background: #ffffff; border: 1px solid #e2e8f0; border-radius: 8px; margin-bottom: 8px;">` +
      `<span style="background: #e0f2fe; color: #0369a1; font-size: 11px; font-weight: 700; padding: 2px 6px; border-radius: 4px; text-transform: uppercase;">Attachment</span> ` +
      `<strong>${att.name || 'File'}</strong> <span style="color: #64748b; font-size: 12px;">(${sizeKb})</span><br/>` +
      `<span style="font-size: 12px; color: #64748b;">Attached directly to this email for download</span>` +
      `</div>`;
  }).join('');

  fileContainerHtml = `<div style="margin: 20px 0; padding: 16px; background-color: #f8fafc; border: 1.5px solid #cbd5e1; border-radius: 10px;">` +
    `<div style="font-weight: 700; font-size: 14px; color: #0f172a; margin-bottom: 4px;">📎 File Retrieval Container</div>` +
    `<div style="font-size: 12px; color: #64748b; margin-bottom: 12px;">The sender attached the following file(s) for you to view or download:</div>` +
    fileCards +
    `</div>`;
}

// Full Email HTML
const emailHtml = `<div style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; max-width: 620px; color: #1e293b; line-height: 1.6; font-size: 14px;">` +
  `<p>Hi there,</p>` +
  `<p>I hope you are having a productive week.</p>` +
  `<p>${item.reason}</p>` +
  fileContainerHtml +
  `<p>Please let me know if you have any questions or need further details.</p>` +
  `<p style="margin-top: 24px;">Best regards,<br/><strong>${item.senderName}</strong><br/><span style="color: #64748b;">${item.senderEmail}</span></p>` +
  `</div>`;

// Process binary attachments for Gmail node
const binary = {};
for (let i = 0; i < attachments.length; i++) {
  const att = attachments[i];
  if (att.source === 'computer' && att.data) {
    try {
      const base64Data = att.data.includes(',') ? att.data.split(',')[1] : att.data;
      const buffer = Buffer.from(base64Data, 'base64');
      const propName = i === 0 ? 'data' : `data_${i}`;
      binary[propName] = await this.helpers.prepareBinaryData(
        buffer,
        att.name || `attachment_${i + 1}.pdf`,
        att.type || 'application/octet-stream'
      );
    } catch (e) {}
  }
}

const formattedResult = `✉️ Email Verified & Sent!\n\n` +
  `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n` +
  `To: ${item.recipient}\n` +
  `From: ${item.senderName} <${item.senderEmail}>\n` +
  `Subject: ${subject}\n` +
  `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n` +
  `${bodyText}\n\n` +
  (attachments.length > 0 ? `📎 Attached Items (${attachments.length}):\n${item.filesContext}\n\n` : '') +
  `✅ Verification: Physical file attached, retrieval container generated, dispatched via Gmail.`;

return {
  json: {
    recipient: item.recipient,
    senderEmail: item.senderEmail,
    senderName: item.senderName,
    subject: subject,
    emailBody: bodyText,
    emailHtml: emailHtml,
    attachmentsCount: attachments.length,
    filesContext: item.filesContext,
    formattedDraft: formattedResult
  },
  binary: Object.keys(binary).length > 0 ? binary : undefined
};

const draft = $('Draft & Prepare Attachments').first().json;
const gmailOutput = $json;

const confirmationText = `🚀 Email & Attachments Delivered!\n\n` +
  `Recipient: ${draft.recipient}\n` +
  (gmailOutput.id ? `Gmail ID: ${gmailOutput.id}\n` : '') +
  `Attachments Sent: ${draft.attachmentsCount}\n\n` +
  draft.formattedDraft;

return {
  status: 'success',
  result: confirmationText,
  recipient: draft.recipient,
  subject: draft.subject,
  messageId: gmailOutput.id || 'sent'
};
